"""In-memory session storage backend."""
import time

from .errors import UnknownSession


class MemoryStore:
    def __init__(self, ttl=None, clock=None):
        self.ttl = ttl
        self.clock = clock if clock is not None else time.monotonic
        self._data = {}

    def _expired(self, sid):
        if self.ttl is None:
            return False
        return (self.clock() - self._data[sid][1]) >= self.ttl

    def get(self, sid):
        if sid not in self._data:
            raise UnknownSession(sid)
        if self._expired(sid):
            del self._data[sid]
            raise UnknownSession(sid)
        return self._data[sid][0]

    def set(self, sid, value):
        self._data[sid] = [value, self.clock()]

    def delete(self, sid):
        self._data.pop(sid, None)

    def touch(self, sid):
        self._data[sid][1] = self.clock()

    def clear(self):
        self._data.clear()

    def keys(self):
        result = []
        for sid, entry in self._data.items():
            if self.ttl is not None and (self.clock() - entry[1]) >= self.ttl:
                continue
            result.append((entry[1], sid))
        result.sort()
        return [sid for _, sid in result]
