"""Schema-driven request validation."""

from .errors import MissingField, BadType, BadValue


def _type_ok(value, expected):
    """Return True if *value* matches *expected* (a type or tuple of types)."""
    types = expected if isinstance(expected, tuple) else (expected,)
    for t in types:
        if t is bool:
            if isinstance(value, bool):
                return True
        elif t is int:
            if isinstance(value, int) and not isinstance(value, bool):
                return True
        elif t is float:
            if isinstance(value, float) and not isinstance(value, bool):
                return True
        else:
            if isinstance(value, t):
                return True
    return False


def validate(obj, schema):
    """Validate *obj* against *schema* and return a new coerced dict.

    Raises the first problem found, checking each field in order:
      1. MissingField  – required field absent
      2. BadType       – value type mismatch
      3. BadValue      – value outside allowed choices
    """
    result = {}

    for name, spec in schema.items():
        required = spec.get('required', False)
        default = spec.get('default', None)
        expected_type = spec.get('type')
        choices = spec.get('choices')

        # --- presence ---
        if name not in obj:
            if required:
                raise MissingField(f"missing required field: {name!r}")
            result[name] = default
            continue

        value = obj[name]

        # --- type ---
        if expected_type is not None and not _type_ok(value, expected_type):
            raise BadType(
                f"field {name!r}: expected {expected_type}, "
                f"got {type(value).__name__}"
            )

        # --- value constraint ---
        if choices is not None and value not in choices:
            raise BadValue(
                f"field {name!r}: value {value!r} not in {choices!r}"
            )

        result[name] = value

    return result
