"""The index object."""
from . import builder


class Index:
    def __init__(self):
        self._idx = {}
        self._docs = 0

    def add(self, doc_id, text):
        self._docs += 1
        for batch in builder.build([(doc_id, text)]):
            builder.merge(self._idx, batch)

    def rebuild(self, pairs):
        self._idx = {}
        self._docs = 0
        seen_docs = set()
        for batch in builder.build(pairs):
            for term, doc_id, positions in batch:
                seen_docs.add(doc_id)
            builder.merge(self._idx, batch)
        self._docs = len(seen_docs)
        total = 0
        for term in self._idx:
            for doc_id in self._idx[term]:
                total += len(self._idx[term][doc_id])
        return total

    def lookup(self, term):
        return sorted(self._idx.get(term, {}).keys())

    def doc_count(self):
        return self._docs

    def terms(self):
        return sorted(self._idx.keys())
