"""CSV reading and writing."""
import csv as _csv
import io
import os


DIALECTS = {'excel': ',', 'excel-tab': '\t', 'pipe': '|'}


class Reader:
    def __init__(self, source, dialect='excel', delimiter=None):
        self.source = source
        self.delimiter = delimiter or DIALECTS.get(dialect, ',')
        self._text = None

    def _get_text(self):
        if self._text is None:
            if hasattr(self.source, 'read'):
                self._text = self.source.read()
            else:
                self._text = self.source
        return self._text

    @property
    def fieldnames(self):
        text = self._get_text()
        reader = _csv.reader(io.StringIO(text), delimiter=self.delimiter)
        for row in reader:
            return [v.strip() for v in row]
        return []

    def rows(self):
        text = self._get_text()
        reader = _csv.reader(io.StringIO(text), delimiter=self.delimiter)
        header = None
        for row in reader:
            if header is None:
                header = [v.strip() for v in row]
                continue
            if all(v.strip() == '' for v in row):
                continue
            d = {}
            for i, key in enumerate(header):
                if i < len(row):
                    d[key] = row[i].strip()
                else:
                    d[key] = None
            yield d

    @classmethod
    def read(cls, path_or_text, dialect='excel', delimiter=None):
        if os.path.exists(path_or_text):
            with open(path_or_text, 'r', newline='') as f:
                text = f.read()
        else:
            text = path_or_text
        return cls(text, dialect=dialect, delimiter=delimiter)

    @classmethod
    def write(cls, path, fieldnames, rows, dialect='excel'):
        delimiter = DIALECTS.get(dialect, ',')
        with open(path, 'w', newline='') as f:
            writer = _csv.writer(f, delimiter=delimiter, quoting=_csv.QUOTE_MINIMAL)
            writer.writerow(fieldnames)
            for row in rows:
                writer.writerow([row.get(k) if row.get(k) is not None else '' for k in fieldnames])
