            elif op == '/':
                if right == 0:
                    raise ExprError("division by zero")
                left = left / right
            elif op == '//':
                if right == 0:
                    raise ExprError("division by zero")
                left = left // right
            else:
                if right == 0:
                    raise ExprError("division by zero")
                left = left % right
        return left

