"""Draining pipeline."""


class DrainError(Exception):
    def __init__(self, message, items=None, cause=None):
        super().__init__(message)
        self.items = list(items or [])
        self.cause = cause


def collect(source, batch_size=100):
    out = []
    try:
        if hasattr(source, 'read_batch'):
            while True:
                batch = source.read_batch(batch_size)
                if not batch:
                    break
                out.extend(batch)
        else:
            for item in source:
                out.append(item)
    except Exception as e:
        raise DrainError(str(e), items=out, cause=e) from e
    finally:
        source.close()
    return out


def drain(source):
    try:
        for item in source:
            yield item
    finally:
        source.close()


def close_all(sources):
    errors = []
    for source in sources:
        try:
            source.close()
        except Exception as e:
            errors.append(e)
    if errors:
        messages = "; ".join(str(e) for e in errors)
        raise DrainError(messages, items=[], cause=errors[0])
