"""Config merge."""
from types import MappingProxyType


class _Drop:
    def __repr__(self):
        return 'DROP'

    def __eq__(self, other):
        return isinstance(other, _Drop)

    def __hash__(self):
        return hash('DROP')


DROP = _Drop()


def _deep_copy(obj):
    """Deep copy dicts/lists, dropping any DROP sentinels."""
    if isinstance(obj, dict):
        return {k: _deep_copy(v) for k, v in obj.items() if not isinstance(v, _Drop)}
    if isinstance(obj, list):
        return [_deep_copy(v) for v in obj if not isinstance(v, _Drop)]
    return obj


def _remove_path(cfg, path):
    """Remove a nested key given a dotted path. Returns a new cfg."""
    parts = path.split('.')
    out = _deep_copy(cfg)
    cur = out
    for part in parts[:-1]:
        if not isinstance(cur, dict) or part not in cur:
            return out
        cur = cur[part]
    last = parts[-1]
    if isinstance(cur, dict) and last in cur:
        del cur[last]
    return out


def _merge_recursive(base, layer, lists):
    """Recursively merge *layer* into a fresh copy of *base*."""
    out = _deep_copy(base)
    for k, v in layer.items():
        if isinstance(v, _Drop):
            if '.' in k:
                out = _remove_path(out, k)
            else:
                out.pop(k, None)
            continue

        if k in out:
            existing = out[k]
            if isinstance(existing, dict) and isinstance(v, dict):
                out[k] = _merge_recursive(existing, v, lists)
            elif isinstance(existing, list) and isinstance(v, list):
                if lists == 'replace':
                    out[k] = _deep_copy(v)
                elif lists == 'concat':
                    out[k] = existing + _deep_copy(v)
                elif lists == 'unique':
                    combined = existing + _deep_copy(v)
                    seen = []
                    for item in combined:
                        if item not in seen:
                            seen.append(item)
                    out[k] = seen
                else:
                    out[k] = _deep_copy(v)
            else:
                out[k] = _deep_copy(v)
        else:
            out[k] = _deep_copy(v)
    return out


def merge(base, *layers, lists='replace'):
    """Merge config layers. Never mutates *base* or any layer."""
    out = _deep_copy(base)
    for layer in layers:
        out = _merge_recursive(out, layer, lists)
    return out


def deep_get(cfg, path, default=None):
    """Read a dotted path from *cfg*."""
    cur = cfg
    for part in path.split('.'):
        if not isinstance(cur, dict) or part not in cur:
            return default
        cur = cur[part]
    return cur


def deep_set(cfg, path, value):
    """Return a NEW config with *path* set, creating intermediate dicts."""
    parts = path.split('.')
    out = _deep_copy(cfg)
    cur = out
    for part in parts[:-1]:
        if part not in cur or not isinstance(cur[part], dict):
            cur[part] = {}
        cur = cur[part]
    cur[parts[-1]] = value
    return out


def _freeze(obj):
    if isinstance(obj, dict):
        return MappingProxyType({k: _freeze(v) for k, v in obj.items()})
    if isinstance(obj, list):
        return tuple(_freeze(v) for v in obj)
    return obj


def freeze(cfg):
    """Return a deeply immutable view (MappingProxyType tree)."""
    return _freeze(cfg)
