            if target in defn['parallel']:
                return {'to': target}
            return None
        if isinstance(defn, list):
            for t in defn:
                if isinstance(t, dict):
                    if t.get('to') == target:
                        return t
                elif t == target:
                    return {'to': target}
            return None
        return None

