        branches = list(defn['parallel'])
        branch_paths = {b: self._compute_branch_path(b) for b in branches}
        self._open_regions[region] = {
            'branches': branches,
            'completed': set(),
            'members': {region},
            'branch_paths': branch_paths,
        }

