        for region, info in self._open_regions.items():
            if state in info['members']:
                return region
        return None

    def _snapshot_regions(self):
        snap = {}
        for k, v in self._open_regions.items():
            snap[k] = {
                'branches': list(v['branches']),
                'completed': set(v['completed']),
                'members': set(v['members']),
