        old_state = self.state
        old_history_len = len(self.history)
        old_regions = self._snapshot_regions()

        # apply state change
        self.state = target
        self.history.append(target)

        # region bookkeeping
        if self._is_parallel(target):
            self._open_region(target)
        elif region is not None:
            self._open_regions[region]['members'].add(target)
            if self._is_terminal(target):
                for branch in self._open_regions[region]['branches']:
                    if target in self._open_regions[region]['branch_paths'].get(branch, set()):
